        Question(50477, "Quel est l'année de l'Indépendance de la Belgique?", listOf("1829", "1830", "1831", "1832"), 1, "Histoire", Difficulty.HARD, explanation = "La Belgique a proclamé son indépendance des Pays-Bas en 1830, après une révolution survenue à Bruxelles en août de cette même année."),
        Question(50478, "Quel est le plus grande mutation génétique découverte?", listOf("Albinisme", "Polydactylie", "Gigantisme", "Nanisme"), 2, "Science", Difficulty.HARD, explanation = "Le gigantisme résulte d'une mutation génétique rare affectant l'hypophyse, entraînant une surproduction d'hormone de croissance. Cette condition est considérée comme la plus grande mutation génétique en termes d'impact sur la taille corporelle."),
        Question(50479, "Quel est le plus grand cimetière du monde?", listOf("Cimetière du Père Lachaise", "Cimetière de Arroios", "Cimetière de Wadi al-Salam", "Cimetière de Calvary"), 2, "Géographie", Difficulty.HARD, explanation = "Situé à Nadjaf en Irak, le cimetière de Wadi al-Salam s'étend sur plusieurs kilomètres carrés et contient plus de cinq millions de tombes, ce qui en fait le plus vaste cimetière du monde."),
        Question(50480, "Quel est le plus ancien festival de théâtre?", listOf("Festival d'Avignon", "Festival de Thespis", "Festival du Dionysia antique", "Festival de Delphi"), 2, "Culture", Difficulty.HARD, explanation = "Le Festival du Dionysia antique, célébré à Athènes dès le VIe siècle avant J.-C., est considéré comme le plus ancien festival de théâtre en l'honneur du dieu Dionysos."),
        Question(50481, "Quel équipe de volleyball a remporté le plus de championnats mondiaux?", listOf("Brésil", "Russie", "Italie", "Japon"), 1, "Sport", Difficulty.HARD, explanation = "L'équipe de Russie (incluant l'URSS) détient le record avec six titres mondiaux, dont quatre sous l'ère soviétique."),
        Question(50482, "Quel réalisateur a créé 'American Fiction'?", listOf("Cord Jefferson", "Barry Jenkins", "Ryan Coogler", "Ava DuVernay"), 0, "Cinéma", Difficulty.HARD, explanation = "Cord Jefferson a réalisé 'American Fiction', son premier long métrage, sorti en 2023 et adapté du roman 'Erasure' de Percival Everett."),
        Question(50483, "Quel est le musicien le plus célèbre du 21ème siècle?", listOf("Beyoncé", "Drake", "Taylor Swift", "The Weeknd"), 2, "Musique", Difficulty.HARD, explanation = "Taylor Swift cumule les records de ventes, de tournées et de récompenses, devenant l'artiste la plus écoutée mondialement sur les plateformes de streaming dans les années 2020."),
        Question(50484, "Quel est l'année de la Révolution haïtienne?", listOf("1790", "1791", "1792", "1793"), 1, "Histoire", Difficulty.HARD, explanation = "La Révolution haïtienne débute en 1791 avec une révolte d'esclaves dans la colonie française de Saint-Domingue, menant à l'indépendance d'Haïti en 1804."),
        Question(50485, "Quel est le plus grand type de lézard?", listOf("Varans de Komodo", "Iguane", "Crocodile", "Alligator"), 0, "Science", Difficulty.EASY, explanation = "Le varan de Komodo, qui peut atteindre trois mètres de long et peser jusqu'à 90 kilos, est le plus grand lézard vivant connu."),
        Question(50486, "Quel est le plus grand réseau fluvial du monde?", listOf("Bassin de l'Amazone", "Bassin du Congo", "Bassin du Yangtze", "Bassin du Mississippi"), 0, "Géographie", Difficulty.HARD, explanation = "Le bassin de l'Amazone est le plus grand réseau fluvial du monde en volume d'eau et en superficie, s'étendant sur environ 7 millions de km² à travers plusieurs pays d'Amérique du Sud."),
        Question(50487, "Quel est le plus ancien type de danse?", listOf("Ballet", "Tango", "Waltz", "Danse rituelle"), 3, "Culture", Difficulty.HARD, explanation = "Les danses rituelles, pratiquées dès la préhistoire lors de cérémonies chamaniques ou religieuses, sont considérées comme la forme la plus ancienne de danse."),
        Question(50488, "Quel athlète de track and field a remporté le plus de titres olympiques?", listOf("Carl Lewis", "Usain Bolt", "Jesse Owens", "Michael Johnson"), 0, "Sport", Difficulty.HARD, explanation = "Carl Lewis a remporté 9 médailles d'or olympiques en athlétisme entre 1984 et 1996, un record masculin partagé avec Paavo Nurmi et Michael Phelps."),
        Question(50489, "Quel réalisateur a créé 'The Iron Claw'?", listOf("Sean Durkin", "Brady Corbet", "Lynne Ramsay", "Claire Denis"), 0, "Cinéma", Difficulty.HARD, explanation = "Sean Durkin est le réalisateur de ce film biographique sur la famille de catcheurs Von Erich, sorti en 2023."),
        Question(50490, "Quel est le plus ancien type de musique enregistrée?", listOf("Classical", "Blues", "Jazz", "Opéra"), 3, "Musique", Difficulty.HARD, explanation = "Le premier enregistrement sonore connu est un extrait de l'opéra \"Les Cloches du Soir\" d'Édouard-Léon Scott de Martinville, réalisé en 1860 sur un phonautographe."),
        Question(50491, "Quel est l'année du Traité de Amiens?", listOf("1801", "1802", "1803", "1804"), 1, "Histoire", Difficulty.HARD, explanation = "Le Traité d'Amiens, signé le 25 mars 1802, mit fin à la guerre entre la France et le Royaume-Uni, marquant une brève période de paix pendant les guerres napoléoniennes."),
        Question(50492, "Quel est le plus grand type de crustacé?", listOf("Araignée de mer géante", "Crabe royal", "Homard géant", "Kraken"), 1, "Science", Difficulty.HARD, explanation = "Le crabe royal, notamment le crabe royal du Kamtchatka, peut atteindre une envergure de pattes de près de 1,8 mètre et peser jusqu'à 12 kg, ce qui en fait le plus grand crustacé."),
        Question(50493, "Quel immense canyon creuse par le fleuve Colorado est l'une des merveilles naturelles des Etats-Unis ?", listOf("Grand Canyon", "Zion Canyon", "Antelope Canyon", "Black Canyon"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le Grand Canyon, situé en Arizona, a été sculpté par le fleuve Colorado sur des millions d'années, atteignant jusqu'à 1 800 mètres de profondeur."),
        Question(50494, "Quel est le plus ancien type de musique vocale?", listOf("Chant grégorien", "Gospel", "Blues", "Rock"), 0, "Culture", Difficulty.HARD, explanation = "Le chant grégorien, développé à partir du IXe siècle, est considéré comme la plus ancienne forme de musique vocale liturgique occidentale codifiée, héritée des traditions juives et byzantines."),
        Question(50495, "Quel équipe de hockey sur glace remporté le plus de Coupes Stanley?", listOf("Montreal Canadiens", "Toronto Maple Leafs", "New York Rangers", "Detroit Red Wings"), 0, "Sport", Difficulty.HARD, explanation = "Les Canadiens de Montréal ont remporté 24 Coupes Stanley, soit le record absolu dans la LNH, devant les Maple Leafs de Toronto (13 titres)."),
        Question(50496, "Quel réalisateur a créé 'The Zone of Interest'?", listOf("Jonathan Glazer", "Todd Field", "Justine Triet", "Charlotte Wells"), 0, "Cinéma", Difficulty.HARD, explanation = "Jonathan Glazer a réalisé ce film en 2023, adapté du roman de Martin Amis, qui explore la vie quotidienne d'une famille nazie vivant juste à côté du camp d'Auschwitz."),
        Question(50497, "Quel est le compositeur symphonique le plus joué?", listOf("Mozart", "Bach", "Beethoven", "Brahms"), 2, "Musique", Difficulty.HARD, explanation = "Beethoven est le compositeur symphonique le plus joué grâce à la popularité intemporelle de ses neuf symphonies, notamment la Cinquième et la Neuvième, qui restent des piliers des répertoires d’orchestres du monde entier."),
        Question(50498, "Quel est l'année du Congrès de Vienne?", listOf("1813", "1814", "1815", "1816"), 2, "Histoire", Difficulty.HARD, explanation = "Le Congrès de Vienne s'est tenu de septembre 1814 à juin 1815, avec sa clôture officielle le 9 juin 1815, pour redessiner les frontières européennes après les guerres napoléoniennes."),
        Question(50499, "Quel est le plus grand type de papillon?", listOf("Papillon Alexandra", "Papillon lune atlas", "Grand Monarque", "Papillon Reine"), 0, "Science", Difficulty.HARD, explanation = "Le papillon Alexandra (Ornithoptera alexandrae) est le plus grand papillon du monde, avec une envergure pouvant atteindre 28 centimètres. Il est endémique des forêts tropicales de Papouasie-Nouvelle-Guinée."),
        Question(50500, "Quel est le plus grand massif montagneux du monde?", listOf("Chaîne de l'Himalaya", "Montagnes Rocheuses", "Chaîne des Andes", "Alpes"), 2, "Géographie", Difficulty.HARD, explanation = "La chaîne des Andes est le plus long massif montagneux continental du monde, s'étendant sur environ 7 000 kilomètres le long de la côte ouest de l'Amérique du Sud."),
        Question(50501, "Quel est le plus ancien opéra jamais écrit?", listOf("La Traviata", "Don Giovanni", "L'Orfeo", "Le Mariage secret"), 2, "Culture", Difficulty.HARD, explanation = "L'Orfeo, composé par Claudio Monteverdi en 1607, est considéré comme le premier opéra majeur de l'histoire, bien que des œuvres antérieures comme Dafne de Peri (1598) existent."),
        Question(50502, "Quel équipe de football remporté la Ligue des Champions 2024?", listOf("Real Madrid", "Manchester City", "Inter Milan", "Bayern Munich"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le Real Madrid a battu le Borussia Dortmund 2-0 en finale à Wembley le 1er juin 2024, décrochant ainsi son 15e titre dans la compétition."),
        Question(50504, "Quel est le plus vieux style de musique urbaine?", listOf("Rap", "Hip-hop", "Funk", "Disco"), 2, "Musique", Difficulty.HARD, explanation = "Le funk est né dans les années 1960 aux États-Unis, mêlant rythmiques syncopées et soul, ce qui en fait l’un des premiers styles de musique urbaine moderne."),
        Question(50505, "Quel est l'année de la Chute de Constantinople?", listOf("1450", "1451", "1452", "1453"), 3, "Histoire", Difficulty.EASY, explanation = "La chute de Constantinople en 1453 marque la fin de l'Empire byzantin et le début de la domination ottomane dans la région."),
        Question(50506, "Quel est le plus grand type d'arachnide non-toxique?", listOf("Araignée de Goliath", "Scorpion géant", "Solifuge géant", "Tailipe"), 0, "Science", Difficulty.HARD, explanation = "L'araignée de Goliath (Theraphosa blondi) est la plus grande espèce d'araignée au monde par son envergure et sa masse, pouvant atteindre 30 centimètres, et elle est considérée comme non-toxique pour l'homme malgré ses chélicères imposantes."),
        Question(50507, "Quel est le plus grand delta fluvial du monde?", listOf("Delta de l'Amazone", "Delta du Gange", "Delta du Mékong", "Delta du Mississippi"), 1, "Géographie", Difficulty.HARD, explanation = "Le delta du Gange-Brahmapoutre, situé principalement au Bangladesh et en Inde, est le plus grand delta du monde en superficie. Il se forme par la confluence des fleuves Gange et Brahmapoutre avant de se jeter dans le golfe du Bengale."),
        Question(50508, "Quel est le plus ancien type de danse de cour?", listOf("Pavan", "Minuet", "Gavotte", "Menuet"), 0, "Culture", Difficulty.HARD, explanation = "La pavan, danse lente et majestueuse, émergea en Italie au XVIe siècle et devint la danse de cour par excellence de la Renaissance européenne."),
        Question(50509, "Quel athlète de saut en longueur a remporté le plus de titres mondiaux?", listOf("Carl Lewis", "Bob Beamon", "Sergei Bubka", "Kliment Voroshilov"), 0, "Sport", Difficulty.HARD, explanation = "Carl Lewis a dominé le saut en longueur avec huit titres mondiaux, dont quatre aux championnats du monde d'athlétisme et quatre aux Jeux olympiques."),
        Question(50510, "Quel réalisateur a créé 'Poor Things'?", listOf("Yorgos Lanthimos", "Jonathan Glazer", "Justine Triet", "Todd Field"), 0, "Cinéma", Difficulty.HARD, explanation = "Yorgos Lanthimos a réalisé 'Poor Things' (2023), une comédie noire fantastique adaptée du roman d'Alasdair Gray, qui a remporté le Lion d'or à Venise."),
        Question(50511, "Quel est le plus ancien style de reggae?", listOf("Roots reggae", "Dancehall", "Ragga", "Ska"), 3, "Musique", Difficulty.HARD, explanation = "Le ska est apparu dans les années 1950 en Jamaïque, combinant des rythmes caribéens avec du jazz et du R&B américain, et il a précédé et influencé le rocksteady puis le reggae."),
        Question(50513, "Quel est le plus grand type de poisson géant?", listOf("Tilapia géante", "Poisson-chat géant", "Arapaima", "Silure géant"), 2, "Science", Difficulty.HARD, explanation = "L'arapaima, aussi appelé pirarucu, est le plus grand poisson d'eau douce d'Amérique du Sud, pouvant atteindre 3 mètres de long et 200 kg."),
        Question(50514, "Quel est le plus grand désert de sable du monde?", listOf("Sahara", "Désert arabique", "Désert de Kyzylkoum", "Désert de Gobi"), 0, "Géographie", Difficulty.HARD, explanation = "Le Sahara est le plus grand désert de sable du monde, s'étendant sur environ 9,2 millions de km² en Afrique du Nord. Il dépasse largement les autres déserts de sable comme le Rub al-Khali en superficie."),
        Question(50515, "Quel est le plus ancien style de musique de chambre?", listOf("Trio", "Quatuor à cordes", "Quintette", "Duo"), 1, "Culture", Difficulty.HARD, explanation = "Le quatuor à cordes, avec deux violons, un alto et un violoncelle, s'est imposé comme le style de musique de chambre le plus ancien et le plus emblématique, notamment grâce à Haydn au XVIIIe siècle."),
        Question(50516, "Quel équipe de tennis a remporté le plus de Billie Jean King Cups?", listOf("États-Unis", "Tchécoslovaquie", "Australie", "Grande-Bretagne"), 0, "Sport", Difficulty.HARD, explanation = "Les États-Unis sont l'équipe la plus titrée de l'histoire de la Billie Jean King Cup, avec 18 victoires, dont la dernière en 2022."),
        Question(50517, "Quel réalisateur a créé 'Anatomy of a Fall'?", listOf("Justine Triet", "Claire Denis", "Lynne Ramsay", "Charlotte Wells"), 0, "Cinéma", Difficulty.HARD, explanation = "Justine Triet a réalisé ce film, qui a remporté la Palme d'Or au Festival de Cannes 2023."),
        Question(50518, "Quel est le plus ancien style de gospel?", listOf("Spirituals", "Gospel traditionnel", "Choir gospel", "Contemporary gospel"), 0, "Musique", Difficulty.HARD, explanation = "Les spirituals sont nés au XVIIIe siècle parmi les esclaves afro-américains, mêlant chants de travail et hymnes religieux, bien avant l'émergence du gospel moderne au début du XXe siècle."),
        Question(50519, "Quel est l'année de la Chute de l'Empire romain d'Occident?", listOf("410", "456", "476", "500"), 2, "Histoire", Difficulty.HARD, explanation = "En 476, le dernier empereur romain d'Occident, Romulus Augustule, est déposé par le chef barbare Odoacre, marquant traditionnellement la fin de l'Empire romain d'Occident."),
        Question(50520, "Quel est le plus grand type de mante religieuse?", listOf("Mante géante", "Mante chinoise", "Mante indienne", "Mante africaine"), 0, "Science", Difficulty.HARD, explanation = "La mante géante (Hierodula grandis) peut atteindre jusqu'à 12 centimètres, ce qui en fait la plus grande espèce de mante religieuse."),
        Question(50521, "Quel est le plus grand système de grottes du monde?", listOf("Grottes de Carlsbad", "Grottes de Chauvet", "Système de Mammoth", "Grottes de Škocjan"), 2, "Géographie", Difficulty.HARD, explanation = "Le Système de Mammoth, situé dans le Kentucky aux États-Unis, est le plus long réseau de grottes connu au monde avec plus de 676 kilomètres explorés."),
        Question(50522, "Quel est le plus ancien concerto jamais écrit?", listOf("Concerto Grosso", "Concerto pour violon", "Concerto pour piano", "Concerto pour cor"), 0, "Culture", Difficulty.HARD, explanation = "Le Concerto Grosso, forme musicale baroque, est considéré comme le plus ancien type de concerto, apparu au XVIIe siècle avec des compositeurs comme Corelli."),
        Question(50523, "Quel équipe de handball a remporté le plus de championnats olympiques?", listOf("France", "Suède", "Russie", "Allemagne"), 2, "Sport", Difficulty.HARD, explanation = "La Russie (y compris l'URSS) a remporté le plus de titres olympiques en handball, avec quatre médailles d'or masculines et une féminine."),
        Question(50525, "Quel est le plus ancien style de musique folklorique documenté?", listOf("Folk irlandais", "Folk écossais", "Musique folklorique chinoise", "Musique folklorique indienne"), 2, "Musique", Difficulty.HARD, explanation = "La musique folklorique chinoise est considérée comme la plus ancienne documentée grâce à des textes et instruments datant de la dynastie Zhou (1046-256 av. J.-C.).")
    )

